window.__BUNDLE = {"body": "<div class=\"wrap\">\n\n  <section id=\"intro\" class=\"stack\" style=\"gap:28px\">\n    <div data-greeting></div>\n    <div id=\"testStart\" class=\"stack\" style=\"gap:28px\" hidden>\n      <div class=\"stack\">\n        <div class=\"eyebrow\">Selbsttest für dich · 10 Minuten</div>\n        <h1>Kompass der Anpassung</h1>\n        <p class=\"lead\">Der Umzug in ein neues Land verändert alles: Sprache, Alltag, Arbeit, Freundeskreis und sogar, wie du dich selbst siehst. Dieser Test hilft dir zu verstehen, wo du gerade auf dem Weg der Anpassung stehst, was schon zur Stütze geworden ist und wohin du den nächsten Schritt machen kannst.</p>\n      </div>\n      <div class=\"roles k-roles\">\n        <div class=\"role ka0\"><b>Sprache</b><span>und Kontakt</span></div>\n        <div class=\"role ka1\"><b>Alltag</b><span>und System</span></div>\n        <div class=\"role ka2\"><b>Arbeit</b><span>und Entfaltung</span></div>\n        <div class=\"role ka3\"><b>Menschen</b><span>und Beziehungen</span></div>\n        <div class=\"role ka4\"><b>Kraft</b><span>Körper und Erholung</span></div>\n        <div class=\"role ka5\"><b>Ich</b><span>und Sinn</span></div>\n      </div>\n      <div class=\"card stack\">\n        <h3>So funktioniert es</h3>\n        <p>Hier gibt es kaum Fragen zu Gefühlen, nur dazu, was du tust. Denk an die letzten 4 Wochen und kreuze an, wie oft das wirklich so war. Es gibt keine richtigen Antworten, nur dein Bild von jetzt.</p>\n        <p>Zuerst kommen zwei kurze Fragen zu deinem Umzug, dann sechs Bereiche deines neuen Lebens und ein kleiner Block über zwei Kulturen: deine eigene und die neue. Am Ende bekommst du eine ausführliche Auswertung mit Bildern, Empfehlungen und Fragen zum Nachdenken. Die Auswertung kannst du als PDF erhalten.</p>\n        <div class=\"scale-legend\"><span><b>0</b> nie</span><span><b>1</b> 1–2 Mal</span><span><b>2</b> ab und zu</span><span><b>3</b> oft</span><span><b>4</b> fast immer</span></div>\n      </div>\n      <div data-testinfo></div>\n      <div class=\"stack\">\n        <h3>Wie heisst du?</h3>\n        <div class=\"row\" style=\"align-items:stretch\">\n          <div class=\"field\"><label for=\"nameMe\">Dein Name</label><input id=\"nameMe\" maxlength=\"30\" autocomplete=\"given-name\" placeholder=\"Zum Beispiel Anna\"></div>\n        </div>\n        <p class=\"note\">Der Name wird nur für eine schöne Auswertung gebraucht.</p>\n      </div>\n      <div><button class=\"btn\" id=\"startBtn\">Test starten</button></div>\n      <div data-share=\"compact\" style=\"margin-top:8px\"></div>\n    </div>\n  </section>\n\n  <section id=\"quiz\" class=\"stack\" hidden style=\"gap:20px\">\n    <div class=\"stack\" style=\"gap:10px\">\n      <div class=\"row\" style=\"justify-content:space-between\">\n        <span class=\"eyebrow\" id=\"stepLabel\"></span>\n        <span class=\"eyebrow\" id=\"countLabel\"></span>\n      </div>\n      <div class=\"progress\"><i id=\"prog\" style=\"width:0\"></i></div>\n    </div>\n    <div class=\"stack\" style=\"gap:6px\">\n      <div><span class=\"part-tag\" id=\"partTag\"></span></div>\n      <h2 id=\"roleTitle\"></h2>\n      <p class=\"muted\" id=\"roleSub\"></p>\n    </div>\n    <div class=\"card\" id=\"qlist\" style=\"padding-block:6px\"></div>\n    <div class=\"row\" style=\"justify-content:space-between\">\n      <button class=\"btn ghost\" id=\"back\">Zurück</button>\n      <button class=\"btn\" id=\"next\" disabled>Weiter</button>\n    </div>\n  </section>\n\n  <section id=\"result\" hidden>\n    <div class=\"rep\" id=\"report\"></div>\n    <div data-share style=\"margin-top:18px\"></div>\n    <div data-lead></div>\n  </section>\n\n  <div data-disclaimer style=\"margin-top:28px\"></div>\n</div>\n<div class=\"pdf-stage\" id=\"stage\" aria-hidden=\"true\"></div>\n", "scripts": ["/* Настройки сайта, общие для всех тестов */\n// Ссылка веб-приложения Google Apps Script (заканчивается на /exec). Одна на все тесты.\nconst ENDPOINT = '';\n// Адрес сайта после размещения, например 'https://irina-tests.netlify.app/' (нужен для ссылок в PDF)\nconst SITE_URL = '';\n// Ссылки на тесты, пока сайт не размещён (используются для кнопки «Поделиться» и блока «Пройди также»).\n// После размещения сайта достаточно заполнить SITE_URL — эти ссылки больше не понадобятся.\nconst TEST_LINKS = {};\n", "const BRAND = 'coach';\nconst TEST_META = { id: 'kompas', name: 'Kompass der Anpassung' };\nconst TEST_INFO = {\n  why: 'Ich habe diesen Fragebogen entwickelt, damit du behutsam auf dein Leben im neuen Land schauen kannst. In der Emigration sieht man leicht nur das, was noch nicht klappt. Der Fragebogen zeigt beides: die Schwierigkeiten und die Stützen, die du schon hast. Und er hilft dir, den nächsten Schritt zu wählen, statt alles auf einmal ändern zu wollen.',\n  gives: [\n    'Du siehst, welche der sechs Bereiche deines neuen Lebens schon zur Stütze geworden sind und welche noch leise klingen.',\n    'Du verstehst, wie du gerade die Verbindung zu deiner eigenen Kultur und zur neuen hältst.',\n    'Du erfährst, in welcher Phase der Anpassung du bist und was dir dort besonders hilft.',\n    'Du bekommst einen Plan mit kleinen Schritten für 4 Wochen und Fragen zum Nachdenken.'\n  ],\n  next: [\n    'Geh behutsam mit dem Ergebnis um: Es ist eine Momentaufnahme der letzten 4 Wochen, keine Bewertung deiner Person.',\n    'Beginne mit einem Bereich und einem kleinen Schritt, nicht mit allem auf einmal.',\n    'Stütz dich auf das, was schon funktioniert: Starke Bereiche helfen, die anderen mitzuziehen.',\n    'Mach den Test in 4 Wochen noch einmal und schau, was sich verändert hat.',\n    'Wenn es sehr schwer wird, sprich mit einem nahestehenden Menschen oder mit einer Fachperson.'\n  ]\n};\n", "/* язык страницы: задаёт загрузчик (ru, uk, de, en) */\nconst DATE_LOCALE = ({ ru:'ru-RU', uk:'uk-UA', de:'de-CH', en:'en-GB' })[(typeof LANG !== 'undefined') ? LANG : 'ru'] || 'ru-RU';\n/* =====================================================================\n   Общие тексты и блоки для всех тестов Ирины Вознесенской.\n   Меняешь здесь — меняется во всех тестах сразу.\n   ===================================================================== */\n\n/* ---------- Обо мне и контакты ---------- */\nconst AUTHOR = {\n  name: 'Iryna Voznesenskaya',\n  about: 'ICF-Coach in der Schweiz und Psychologin in der Ukraine.',\n  coach: { place: 'Schweiz · Zürich', title: 'Coach', text: 'Transformations-Coach und Neurocoach, ICF. Ich begleite russischsprachige Emigrantinnen und Emigranten durch die Anpassung: sich selbst und den eigenen Platz in der neuen Welt zu finden. In der Schweiz arbeite ich ausschliesslich als Coach. Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Behandlung.',\n           instagram: 'https://www.instagram.com/iryna.voznesenskaya/', telegram: 'https://t.me/IrynaNeuroCoach_channel' },\n  psy:   { place: 'Ukraine · Kyjiw', title: 'Psychologin in der Ukraine', text: 'Ich arbeite mit Paarbeziehungen: Ich helfe Paaren, einander zu hören, Nähe zurückzugewinnen und ein Gleichgewicht zu finden. Als Psychologin arbeite ich nur mit Klientinnen und Klienten in der Ukraine, auf Grundlage meiner ukrainischen Qualifikation.',\n           instagram: 'https://www.instagram.com/voznesenskayairyna.psy/', telegram: 'https://t.me/IrynaVoznesenska_psy' }\n};\n\n/* ---------- Все тесты (для главной и блока «Пройди также») ---------- */\nconst TESTS = [\n  { id: 'roza-lyubvi', path: 'roza-lyubvi/index.html', name: 'Die Rose der Liebe', brand: 'psy', tag: 'Für Paare · 15 Minuten',\n    text: 'Drei Rollen in der Beziehung: Anziehung, Nähe und Verantwortung. Finde heraus, welche Rollen deutlich klingen, welche leiser geworden sind und wie ihr einander begegnet.' },\n  { id: 'kompas', path: 'kompas/index.html', name: 'Kompass der Anpassung', brand: 'coach', tag: 'Für dich · 10 Minuten',\n    text: 'Wo du gerade in der Emigration stehst: sechs Bereiche deines neuen Lebens, dein Weg zwischen zwei Kulturen und der nächste kleine Schritt.' }\n];\n\nconst handle = url => '@' + url.replace(/\\/+$/, '').split('/').pop();\nconst pickOne = arr => arr[Math.floor(Math.random() * arr.length)];\nconst BASE = (typeof SITE_BASE !== 'undefined') ? SITE_BASE : '../';\n\nfunction practiceHtml(key){\n  const p = AUTHOR[key];\n  const links = [\n    p.instagram ? `<a href=\"${p.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram ${handle(p.instagram)}</a>` : '',\n    p.telegram ? `<a href=\"${p.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram-Kanal</a>` : ''\n  ].filter(Boolean).join('');\n  return `<div class=\"practice ${key}\"><span class=\"place\">${p.place}</span><h4>${p.title}</h4><p>${p.text}</p><div class=\"links\">${links}</div></div>`;\n}\nfunction authorHtml(label = 'Über die Autorin des Tests'){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  return `<div class=\"blk author\"><div class=\"eyebrow\">${label}</div>\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${AUTHOR.name}</b><span>${AUTHOR.about}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div></div>`;\n}\nfunction footerLine(){\n  return BRAND === 'coach' ? 'Iryna Voznesenskaya · ICF-Coach (Schweiz) · Psychologin (Ukraine)' : 'Iryna Voznesenskaya · Psychologin (Ukraine) · ICF-Coach (Schweiz)';\n}\n\n/* ---------- Приветствие и обязательный мини-опрос ---------- */\nconst SURVEY = {\n  heard: { q: 'Woher kennst du mich?', opts: ['Instagram','Telegram','Empfehlung von Freunden oder Bekannten','Google-Suche','Facebook','Anderes'] },\n  interest: { q: 'Was interessiert dich?', opts: ['Psychologie: Beziehung als Paar','Coaching: Anpassung in der Emigration und zu sich selbst finden','Einfach so, aus Neugier'] }\n};\nconst GREET = {\n  head: ['Hallo! Ich bin {A}','Schön, dass du da bist! Ich heisse {A}','Willkommen! Ich bin {A}','Grüss dich! Ich bin {A}'],\n  about: ['ICF-Coach in der Schweiz und Psychologin in der Ukraine.','Ich arbeite in zwei Ländern: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.','Ich helfe Menschen, zu sich selbst zu finden und warme Beziehungen aufzubauen: als ICF-Coach in der Schweiz und als Psychologin in der Ukraine.'],\n  ask: ['Beantworte bitte vor dem Test zwei kurze Fragen. So verstehe ich besser, wie ich dir nützlich sein kann.',\n        'Zwei kurze Fragen vor dem Start, und dann geht es direkt zum Test.',\n        'Mir ist wichtig zu wissen, wer meine Tests macht. Beantworte bitte zwei kurze Fragen.']\n};\nfunction greetingHtml(){\n  const order = BRAND === 'coach' ? ['coach','psy'] : ['psy','coach'];\n  const group = key => `<fieldset class=\"survey\"><legend>${SURVEY[key].q} *</legend>${SURVEY[key].opts.map((o, i) =>\n    `<label class=\"check\"><input type=\"checkbox\" id=\"sv-${key}-${i}\" data-sv=\"${key}\" value=\"${o}\"> <span>${o}</span></label>`).join('')}</fieldset>`;\n  return `<div class=\"blk author greet\">\n    <div class=\"who\"><div class=\"mono\">IV</div><div><b>${pickOne(GREET.head).replace('{A}', AUTHOR.name)}</b><span>${pickOne(GREET.about)}</span></div></div>\n    <div class=\"practices\">${order.map(practiceHtml).join('')}</div>\n    <div class=\"stack\" style=\"gap:10px\"><p class=\"note\">${pickOne(GREET.ask)} Du kannst mehrere Antworten ankreuzen.</p>\n      <div class=\"surveys\">${group('heard')}${group('interest')}</div>\n      <p class=\"err\" id=\"svErr\" hidden></p>\n      <div><button class=\"btn\" type=\"button\" id=\"svGo\">Weiter zum Test</button></div></div></div>`;\n}\nfunction surveyAnswers(){\n  const pick = key => [...document.querySelectorAll(`input[data-sv=\"${key}\"]:checked`)].map(i => i.value);\n  return { heard: pick('heard'), interest: pick('interest') };\n}\n\n/* ---------- Живое приглашение в работу (тексты каждый раз собираются заново) ---------- */\nconst INVITES = {\n  psy: {\n    open: ['{N}, danke für deine ehrlichen Antworten.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich auf eure Beziehung.',\n           '{N}, diese Auswertung ist erst der Anfang eines Gesprächs.',\n           '{N}, der Test zeigt ein Bild, echte Veränderung beginnt im Gespräch.',\n           '{N}, hinter jeder Zahl in dieser Auswertung steht deine Geschichte.'],\n    body: ['Die Zahlen zeigen, wo es in eurer Beziehung still geworden ist. Doch dahinter steht immer etwas Eigenes: Müdigkeit, Kränkungen, Gewohnheiten, unausgesprochene Erwartungen. Im Gespräch schauen wir behutsam auf deine Situation und finden erste Schritte, damit {F}.',\n           'Manchmal genügt eine einzige treffende Frage, damit ein Paar einander wieder hört. Wenn du dir wünschst, dass {F}, lade ich dich zu einem Gespräch ein: ruhig, behutsam, ohne Bewertung.',\n           'Beziehungen verändern sich nicht durch Wissen, sondern durch neue Handlungen. Ich helfe Paaren, diese Handlungen zu finden und sie nicht nach einer Woche wieder aufzugeben. Lass uns gemeinsam schauen, was es braucht, damit {F}.',\n           'Den Weg zur Veränderung kann man allein gehen oder mit Unterstützung. Im Gespräch schauen wir dein Dreieck an und überlegen, was es braucht, damit {F}.',\n           'Viele Paare leben jahrelang mit derselben Spannung, weil sie nicht wissen, wie sie das Gespräch beginnen sollen. Ich helfe dir, es so zu beginnen, dass {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir besprechen dein Ergebnis und entscheiden, ob eine weitere Arbeit an der Beziehung sinnvoll ist.',\n           '30 Minuten online. Du erzählst, ich höre zu und stelle Fragen. Nach dem Gespräch wird klarer, was in eurer Beziehung passiert und wo du anfangen kannst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und einen Weg für die Arbeit an der Beziehung zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über eure Beziehung sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Psychologische Beratungen finden online für Klientinnen und Klienten in der Ukraine statt.'\n  },\n  coach: {\n    open: ['{N}, danke, dass du dir Zeit für dich nimmst.',\n           '{N}, du machst schon einen wichtigen Schritt: Du schaust ehrlich und behutsam auf dich.',\n           '{N}, diese Auswertung ist erst der Anfang des Weges.',\n           '{N}, manchmal öffnet ein Test mehr Fragen als Antworten. Und das ist gut so.',\n           '{N}, alles, was du jetzt siehst, kann zu einer Stütze werden.'],\n    body: ['Die Emigration verändert alles: Sprache, Gewohnheiten, Rollen in der Familie und sogar, wie wir uns selbst sehen. Im Coaching suchen wir deine Stützen in der neuen Welt und helfen dir Schritt für Schritt, {F}.',\n           'Wenn sich das Land ändert, verändern auch wir uns. Manchmal fühlt sich das an, als würde man sich selbst verlieren. Ich helfe dir, dich neu zu finden, um {F}.',\n           'Du hast schon einen grossen Weg hinter dir. Coaching hilft dir, diese Erfahrung in Kraft zu verwandeln und {F}.',\n           'Die Antworten sind schon in dir, aber im Trubel des neuen Lebens sind sie schwer zu hören. In der Arbeit mit mir findest du deine Antworten und entscheidest, was dir hilft, {F}.',\n           'Anpassung bedeutet nicht nur Papiere und Sprache. Es ist die Suche nach dem eigenen Platz. Lass uns gemeinsam schauen, was dir hilft, {F}.'],\n    cta:  ['Melde dich für ein Kennenlerngespräch von 30 Minuten an: Wir sprechen über dein Anliegen und darüber, wie die Arbeit an dir selbst aussehen kann.',\n           '30 Minuten online. Du erzählst, was dir gerade wichtig ist, ich stelle Fragen. Nach dem Gespräch wird klarer, wohin du gehen willst.',\n           'Das erste Gespräch dauert 30 Minuten. Das reicht, um dein Anliegen zu verstehen und erste Schritte zu skizzieren.'],\n    title: ['Ich lade dich zu einem Gespräch von 30 Minuten ein','Lass uns über dich sprechen','Der nächste Schritt: ein Gespräch'],\n    legal: 'Coaching ist keine Psychotherapie und ersetzt keine psychologische oder medizinische Behandlung.'\n  }\n};\nconst INVITE_FOCUS_DEFAULT = { psy: 'in eurer Beziehung mehr Wärme und Verständnis entsteht', coach: 'deinen Platz in der neuen Welt zu finden' };\nlet inviteSeed = null;\nfunction resetInvite(){ inviteSeed = null; }\nfunction invitePractice(country){\n  // как психолог Ирина работает только с клиентами в Украине; остальных приглашаем в коучинг\n  if (BRAND === 'psy' && country && country !== 'Украина') return 'coach';\n  return BRAND;\n}\nfunction inviteHtml(ctx){\n  if (!inviteSeed) inviteSeed = Array.from({length:6}, () => Math.random());\n  const key = invitePractice(ctx.country);\n  const P = INVITES[key], A = AUTHOR[key];\n  const pick = (arr, i) => arr[Math.floor(inviteSeed[i] * arr.length)];\n  const N = ctx.name || '';\n  const F = (ctx.focus && ctx.focus[key]) || INVITE_FOCUS_DEFAULT[key];\n  const fill = t => { let s = N ? t.replace('{N}', N) : t.replace('{N}, ', ''); s = s.replace('{F}', F); return s.charAt(0).toUpperCase() + s.slice(1); };\n  const links = [A.telegram ? `<a href=\"${A.telegram}\" target=\"_blank\" rel=\"noopener\">Telegram: ${A.telegram.replace('https://','')}</a>` : '',\n                 A.instagram ? `<a href=\"${A.instagram}\" target=\"_blank\" rel=\"noopener\">Instagram: ${handle(A.instagram)}</a>` : ''].filter(Boolean);\n  const other = key === 'psy' ? 'coach' : 'psy';\n  const wantsOther = (ctx.interest || []).some(x => other === 'coach' ? /^Coaching/.test(x) : /^Psychologie/.test(x));\n  const otherLine = wantsOther && !(other === 'psy' && ctx.country && ctx.country !== 'Украина')\n    ? `<p class=\"note\">Dich interessiert auch die Richtung «${AUTHOR[other].title}». Mehr über diese Arbeit erfährst du hier: <a href=\"${AUTHOR[other].telegram}\" target=\"_blank\" rel=\"noopener\">${AUTHOR[other].telegram.replace('https://','')}</a></p>` : '';\n  return `<div class=\"blk invite ${key}\">\n    <div class=\"eyebrow\">${key === 'psy' ? 'Arbeit an der Beziehung' : 'Arbeit an dir selbst'}</div>\n    <h2>${pick(P.title, 0)}</h2>\n    <p class=\"lead\"><b>${fill(pick(P.open, 1))}</b></p>\n    <p>${fill(pick(P.body, 2))}</p>\n    <div class=\"invite-cta\"><p>${fill(pick(P.cta, 3))}</p>\n      <p><b>So meldest du dich an:</b> Schreib mir das Wort <b>«TERMIN»</b>, und ich schlage dir eine passende Zeit vor.</p>\n      <div class=\"invite-links\">${links.join('')}</div></div>\n    ${otherLine}\n    <p class=\"note\">${P.legal}</p></div>`;\n}\n\n/* ---------- Пройди также ---------- */\nfunction testUrl(t){\n  if (typeof SITE_URL !== 'undefined' && SITE_URL) return SITE_URL.replace(/\\/?$/, '/') + t.path;\n  if (typeof TEST_LINKS !== 'undefined' && TEST_LINKS[t.id]) return TEST_LINKS[t.id];\n  return BASE + t.path;\n}\nfunction moreTestsHtml(currentId){\n  const list = TESTS.filter(t => t.id !== currentId);\n  if (!list.length) return '';\n  return `<div class=\"blk more\"><div class=\"eyebrow\">Mach auch diesen Test</div>\n    <div class=\"tcards\">${list.map(t => `<a class=\"tcard ${t.brand}\" href=\"${testUrl(t)}\" target=\"_blank\" rel=\"noopener\">\n      <span class=\"ttag\">${t.tag}</span><b>${t.name}</b><span>${t.text}</span><span class=\"tgo\">Zum Test →</span></a>`).join('')}</div></div>`;\n}\n\n/* ---------- Об этом опроснике + дисклеймер ---------- */\nconst DISCLAIMER = [\n  'Dieser Fragebogen ist ein Werkzeug zur Selbsterkenntnis und für Gespräche. Er ist keine psychologische oder medizinische Diagnostik und kein psychotherapeutischer Befund und ersetzt keine Beratung durch eine Fachperson.',\n  'Die Ergebnisse spiegeln deine persönliche Wahrnehmung der letzten 4 Wochen wider und können sich verändern.',\n  'Wenn du eine Krise, Gewalt oder eine Bedrohung deiner Sicherheit erlebst, wende dich an eine Fachperson oder an die Notdienste deines Landes.'\n];\nfunction testInfoHtml(){\n  if (typeof TEST_INFO === 'undefined') return '';\n  return `<div class=\"blk testinfo\"><div class=\"eyebrow\">Über diesen Fragebogen</div>\n    <p class=\"lead\">${TEST_INFO.why}</p>\n    <div class=\"ti-cols\">\n      <div><h3>Was dir der Test gibt</h3><ul class=\"clean\">${TEST_INFO.gives.map(x => `<li>${x}</li>`).join('')}</ul></div>\n      <div><h3>Was du damit tun kannst</h3><ul class=\"clean\">${TEST_INFO.next.map(x => `<li>${x}</li>`).join('')}</ul></div>\n    </div></div>`;\n}\nfunction disclaimerHtml(){\n  return `<div class=\"disclaimer\"><b>Wichtig</b>${DISCLAIMER.map(x => `<p>${x}</p>`).join('')}</div>`;\n}\n\n/* ---------- Поделиться тестом ---------- */\nconst SHARE_TEXT = {\n  'roza-lyubvi': ['Ich habe den Paartest «Die Rose der Liebe» gemacht. Spannend und sehr treffend. Mach ihn auch, dann vergleichen wir:',\n                  'Ich habe den Test «Die Rose der Liebe» entdeckt: 15 Minuten, und man sieht, welche Rollen in der Beziehung deutlich klingen und welche leiser geworden sind. Probier es aus:'],\n  'kompas':      ['Ich habe den Test «Kompass der Anpassung» gemacht, für alle, die in der Emigration leben. Er hilft sehr zu verstehen, wo man gerade steht. Probier es aus:',\n                  'Ich habe den Test «Kompass der Anpassung» entdeckt: 10 Minuten, und man sieht, was im neuen Land schon zur Stütze geworden ist und wo es noch still ist. Probier es aus:']\n};\nconst SHARE_ICON = {\n  share: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M12 3v12M7 8l5-5 5 5M5 13v6a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-6\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/></svg>',\n  wa: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M4 20l1.2-4A8 8 0 1 1 8 18.8z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M9 9.5c0 3 2.5 5.5 5.5 5.5l1-1.5-2-1-1 1c-1-.5-1.5-1-2-2l1-1-1-2z\" fill=\"currentColor\"/></svg>',\n  tg: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 4 3 11l6 2 2 6 3-4 5 4z\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"m9 13 8-6\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>',\n  copy: '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"8\" y=\"8\" width=\"12\" height=\"12\" rx=\"2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/><path d=\"M16 8V6a2 2 0 0 0-2-2H6a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h2\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\"/></svg>'\n};\nfunction shareData(){\n  const t = TESTS.find(x => typeof TEST_META !== 'undefined' && x.id === TEST_META.id) || TESTS[0];\n  return { url: testUrl(t), text: pickOne(SHARE_TEXT[t.id] || ['Probier diesen Test aus:']), title: t.name };\n}\nfunction shareHtml(compact){\n  if (typeof TEST_META === 'undefined') return '';\n  const head = compact\n    ? `<p class=\"note\">Kennst du jemanden, dem dieser Test auch helfen könnte? Leite den Link weiter.</p>`\n    : `<div class=\"eyebrow\">Teilen</div><h3>Schick den Test deinen Freundinnen und Freunden</h3><p>Wenn dir der Test geholfen hat, schick ihn Menschen, denen er auch helfen kann. ${TEST_META.id === 'roza-lyubvi' ? 'Noch besser: Schlag deinem Partner oder deiner Partnerin vor, ihn auch zu machen, und vergleicht eure Ergebnisse.' : 'Vor allem denen, die auch vor kurzem umgezogen sind.'}</p>`;\n  return `<div class=\"${compact ? 'share compact' : 'blk share'}\">${head}\n    <div class=\"share-btns\">\n      ${navigator.share ? `<button type=\"button\" class=\"main\" data-share-act=\"native\">${SHARE_ICON.share}Teilen</button>` : ''}\n      <button type=\"button\" data-share-act=\"wa\">${SHARE_ICON.wa}WhatsApp</button>\n      <button type=\"button\" data-share-act=\"tg\">${SHARE_ICON.tg}Telegram</button>\n      <button type=\"button\" data-share-act=\"copy\">${SHARE_ICON.copy}Link kopieren</button>\n    </div>\n    <div class=\"share-link\" hidden><input readonly aria-label=\"Link zum Test\"></div>\n    <span class=\"share-ok\" hidden></span></div>`;\n}\nfunction openExternal(url){\n  const w = window.open(url, '_blank', 'noopener');\n  if (!w) location.href = url;\n}\ndocument.addEventListener('click', async (ev) => {\n  const b = ev.target.closest('[data-share-act]'); if (!b) return;\n  const box = b.closest('.share'), d = shareData(), act = b.dataset.shareAct;\n  const ok = box.querySelector('.share-ok');\n  const showOk = t => { ok.textContent = t; ok.hidden = false; setTimeout(() => ok.hidden = true, 4000); };\n  if (act === 'native'){\n    try { await navigator.share({ title: d.title, text: d.text, url: d.url }); return; }\n    catch(e){ if (e && e.name === 'AbortError') return; }\n  }\n  if (act === 'wa') return openExternal('https://wa.me/?text=' + encodeURIComponent(d.text + ' ' + d.url));\n  if (act === 'tg') return openExternal('https://t.me/share/url?url=' + encodeURIComponent(d.url) + '&text=' + encodeURIComponent(d.text));\n  try { await navigator.clipboard.writeText(d.text + ' ' + d.url); showOk('Link kopiert. Füge ihn in eine Nachricht an eine Freundin oder einen Freund ein.'); }\n  catch(e){\n    const row = box.querySelector('.share-link'), inp = row.querySelector('input');\n    inp.value = d.url; row.hidden = false; inp.focus(); inp.select();\n    showOk('Kopiere den Link aus dem Feld oben.');\n  }\n});\n\n/* ---------- Отрисовка общих блоков на странице ---------- */\ndocument.documentElement.dataset.brand = BRAND;\ndocument.querySelectorAll('[data-author]').forEach(el => el.innerHTML = authorHtml());\ndocument.querySelectorAll('[data-greeting]').forEach(el => el.innerHTML = greetingHtml());\ndocument.querySelectorAll('[data-testinfo]').forEach(el => el.innerHTML = testInfoHtml());\ndocument.querySelectorAll('[data-disclaimer]').forEach(el => el.innerHTML = disclaimerHtml());\ndocument.querySelectorAll('[data-share]').forEach(el => el.innerHTML = shareHtml(el.dataset.share === 'compact'));\n(function(){\n  const go = document.getElementById('svGo'); if (!go) return;\n  go.addEventListener('click', () => {\n    const a = surveyAnswers(), err = document.getElementById('svErr');\n    const miss = !a.heard.length ? 'Kreuze bitte an, woher du mich kennst.' : !a.interest.length ? 'Kreuze bitte an, was dich interessiert.' : '';\n    err.textContent = miss; err.hidden = !miss;\n    if (miss) return;\n    document.querySelector('[data-greeting]').hidden = true;\n    document.getElementById('testStart').hidden = false;\n    window.scrollTo(0, 0);\n  });\n})();\n", "/* ---------- схемы «Компаса адаптации» ----------\n   Простые линейные схемы на фоне страницы: тонкие линии, один акцентный цвет, без картинок. */\nconst LN = { ink:'#3A322B', muted:'#9A8D7E', line:'#D8CDBE', acc:'#8A5A3B', soft:'#EFE6D8' };\nconst sf = (x, y, t, o = {}) => `<text x=\"${x}\" y=\"${y}\" text-anchor=\"${o.a || 'middle'}\" font-family=\"${o.serif ? 'Forum, Georgia, serif' : 'Manrope, sans-serif'}\" font-size=\"${o.s || 12}\" font-weight=\"${o.w || 400}\" fill=\"${o.c || LN.ink}\" ${o.ls ? `letter-spacing=\"${o.ls}\"` : ''}>${t}</text>`;\n\n/* Обложка: тонкий компас */\nfunction compassSVG(){\n  const c = 70;\n  let s = `<svg viewBox=\"0 0 140 140\" role=\"img\" aria-label=\"Kompass\" width=\"150\" height=\"150\">\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"60\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.2\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"52\" fill=\"none\" stroke=\"${LN.line}\" stroke-width=\"1\"/>`;\n  for (let k = 0; k < 24; k++){ const a = k * Math.PI / 12, r1 = k % 6 === 0 ? 44 : 49; s += `<line x1=\"${(c + r1 * Math.cos(a)).toFixed(1)}\" y1=\"${(c + r1 * Math.sin(a)).toFixed(1)}\" x2=\"${(c + 52 * Math.cos(a)).toFixed(1)}\" y2=\"${(c + 52 * Math.sin(a)).toFixed(1)}\" stroke=\"${LN.ink}\" stroke-width=\"${k % 6 === 0 ? 1.2 : .7}\"/>`; }\n  s += `<path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c} ${c + 38} L${c - 7} ${c}Z\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.1\"/>\n    <path d=\"M${c} ${c - 38} L${c + 7} ${c} L${c - 7} ${c}Z\" fill=\"${LN.acc}\"/>\n    <circle cx=\"${c}\" cy=\"${c}\" r=\"3\" fill=\"${LN.ink}\"/>` + sf(c, 20, 'N', { serif:true, s:12 });\n  return s + '</svg>';\n}\n\n/* Две культуры: схема 2 × 2 и точка — где человек сейчас */\nfunction shoresSVG(own, neu){\n  const W = 520, H = 420, x0 = 90, y0 = 30, S = 340;               // поле S×S\n  const px = x0 + S * neu / 20, py = y0 + S * (1 - own / 20);\n  const q = [['Eigene Insel', 0, 0], ['Brücke zwischen den Welten', 1, 0], ['Zwischen zwei Ufern', 0, 1], ['Neues Leben ganz von vorn', 1, 1]];\n  const mine = (own >= 10 ? 0 : 1) * 2 + (neu >= 10 ? 1 : 0);\n  // цвета по спирали: своя культура — фиолетовый, мост — бирюзовый, между берегами — бежевый, новая культура — жёлтый\n  const QF = ['#EDEBF8', '#E1F5F6', '#F3F1EC', '#F9F5DE'], QL = ['#6A5FB8', '#2894A0', '#8E8470', '#A99A2E'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Schema: eigene und neue Kultur\">`;\n  q.forEach(([t, cx, cy], i) => {\n    const x = x0 + cx * S / 2, y = y0 + cy * S / 2;\n    s += `<rect x=\"${x}\" y=\"${y}\" width=\"${S / 2}\" height=\"${S / 2}\" fill=\"${QF[i]}\" opacity=\"${i === mine ? 1 : .35}\"/>`;\n    const words = t.split(' '), mid = Math.ceil(words.length / 2);\n    const l1 = words.length > 2 ? words.slice(0, mid).join(' ') : t, l2 = words.length > 2 ? words.slice(mid).join(' ') : '';\n    s += sf(x + S / 4, y + S / 4 - (l2 ? 4 : -4), l1, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n    if (l2) s += sf(x + S / 4, y + S / 4 + 20, l2, { serif:true, s:19, c: i === mine ? QL[i] : LN.muted });\n  });\n  s += `<rect x=\"${x0}\" y=\"${y0}\" width=\"${S}\" height=\"${S}\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1\"/>\n    <line x1=\"${x0 + S / 2}\" y1=\"${y0}\" x2=\"${x0 + S / 2}\" y2=\"${y0 + S}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>\n    <line x1=\"${x0}\" y1=\"${y0 + S / 2}\" x2=\"${x0 + S}\" y2=\"${y0 + S / 2}\" stroke=\"${LN.line}\" stroke-dasharray=\"3 4\"/>`;\n  [0, 10, 20].forEach(v => {\n    s += sf(x0 + S * v / 20, y0 + S + 18, v, { c:LN.muted, s:11 }) + sf(x0 - 10, y0 + S * (1 - v / 20) + 4, v, { a:'end', c:LN.muted, s:11 });\n  });\n  s += sf(x0 + S / 2, y0 + S + 42, 'Verbindung zur neuen Kultur →', { c:LN.muted, s:12, ls:'.5' });\n  s += `<text transform=\"translate(${x0 - 40} ${y0 + S / 2}) rotate(-90)\" text-anchor=\"middle\" font-family=\"Manrope, sans-serif\" font-size=\"12\" letter-spacing=\".5\" fill=\"${LN.muted}\">Verbindung zur eigenen Kultur →</text>`;\n  s += `<line x1=\"${px}\" y1=\"${y0 + S}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/><line x1=\"${x0}\" y1=\"${py}\" x2=\"${px}\" y2=\"${py}\" stroke=\"${QL[mine]}\" stroke-dasharray=\"2 3\"/>\n    <circle cx=\"${px}\" cy=\"${py}\" r=\"9\" fill=\"${QL[mine]}\"/><circle cx=\"${px}\" cy=\"${py}\" r=\"15\" fill=\"none\" stroke=\"${QL[mine]}\" stroke-width=\"1\"/>`;\n  s += sf(px + (px > x0 + S - 60 ? -22 : 22), py - 16, 'du bist hier', { a: px > x0 + S - 60 ? 'end' : 'start', c:QL[mine], w:700, s:15 });\n  return s + '</svg>';\n}\n\n/* Шесть сфер: дорожки 0–20, каждая сфера в своей рамке */\nfunction flowerSVG(sc){\n  const W = 560, rowH = 56, H = 30 + rowH * sc.length, x0 = 168, x1 = 486;\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Sechs Bereiche\">`;\n  const max = Math.max(...sc), min = Math.min(...sc);\n  sc.forEach((v, k) => {\n    const y = 30 + k * rowH, x = x0 + (x1 - x0) * v / 20, hi = v === max || v === min;\n    const col = css(AC[k]), soft = css(AS[k]);\n    s += `<rect x=\"4\" y=\"${y - 22}\" width=\"${W - 8}\" height=\"44\" rx=\"10\" fill=\"${soft}\" stroke=\"${col}\" stroke-width=\"1.2\"/>`;\n    s += `<g transform=\"translate(20 ${y - 12})\">${aIcon(k).replace(/^<svg[^>]*>/, '').replace(/<\\/svg>$/, '')}</g>`;\n    s += sf(54, y + 6, AREAS[k].short, { a:'start', serif:true, s:19, c: col });\n    [5, 10, 15].forEach(t => { const tx = x0 + (x1 - x0) * t / 20; s += `<line x1=\"${tx}\" y1=\"${y - 7}\" x2=\"${tx}\" y2=\"${y + 7}\" stroke=\"${col}\" stroke-width=\".8\" opacity=\".35\"/>`; });\n    s += `<line x1=\"${x0}\" y1=\"${y}\" x2=\"${x1}\" y2=\"${y}\" stroke=\"#fff\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <line x1=\"${x0}\" y1=\"${y}\" x2=\"${x}\" y2=\"${y}\" stroke=\"${col}\" stroke-width=\"6\" stroke-linecap=\"round\"/>\n      <circle cx=\"${x}\" cy=\"${y}\" r=\"${hi ? 9 : 7}\" fill=\"${col}\" stroke=\"#fff\" stroke-width=\"2\"/>`;\n    s += sf(x1 + 18, y + 6, `${v}/20`, { a:'start', s:14, w:700, c: col });\n  });\n  [0, 10, 20].forEach(v => { const x = x0 + (x1 - x0) * v / 20; s += sf(x, H - 2, v, { c:LN.muted, s:10 }); });\n  return s + '</svg>';\n}\n\n/* Путь адаптации: линия с этапами */\nfunction journeySVG(stage){\n  const W = 560, H = 190;\n  const P = [[50, 60], [200, 140], [360, 100], [510, 40]], names = ['Entdeckungen','Schwierigkeiten','Halt','Wie zu Hause'];\n  let s = `<svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"Weg der Anpassung\">`;\n  s += `<path d=\"M50 60 C110 60 140 140 200 140 S310 100 360 100 S460 40 510 40\" fill=\"none\" stroke=\"${LN.ink}\" stroke-width=\"1.4\"/>`;\n  if (stage === 4) s += `<path d=\"M360 100 C390 150 300 175 280 140 C265 112 320 95 360 100\" fill=\"none\" stroke=\"${LN.acc}\" stroke-width=\"1.4\" stroke-dasharray=\"4 4\"/>`;\n  P.forEach(([x, y], i) => {\n    const on = i === stage;\n    s += `<circle cx=\"${x}\" cy=\"${y}\" r=\"${on ? 9 : 6}\" fill=\"${on ? LN.acc : '#fff'}\" stroke=\"${on ? LN.acc : LN.ink}\" stroke-width=\"1.4\"/>`;\n    s += sf(x, y + (i === 1 ? 30 : 28), names[i], { serif:true, s:16, c: on ? LN.acc : LN.ink });\n  });\n  const at = stage === 4 ? [300, 165] : P[stage];\n  s += sf(at[0], at[1] - 18, stage === 4 ? 'neue Runde · du bist hier' : 'du bist hier', { s:12, w:700, c:LN.acc, ls:'.4' });\n  return s + '</svg>';\n}\n", "/* =====================================================================\n   «Компас адаптации» — коучинговый самотест про адаптацию в эмиграции.\n   ===================================================================== */\nconst AREAS = [\n  { name: 'Sprache und Kontakt', short: 'Sprache',\n    items: ['Ich spreche die Landessprache in Alltagssituationen, auch wenn ich Fehler mache.',\n            'Ich lerne die Sprache: Unterricht, App, Bücher, Serien.',\n            'Ich beginne selbst Gespräche mit Einheimischen und beantworte nicht nur Fragen.',\n            'Ich lese Briefe, Websites und Aushänge in der Landessprache ohne Übersetzer oder mit wenig Hilfe.',\n            'Ich frage nach und bitte um Erklärung, wenn ich etwas nicht verstehe, statt zu schweigen.'],\n    lv: ['Die Sprache klingt noch leise. Das ist normal: Die Sprache ist eine der grössten Belastungen in der Emigration, und viele brauchen Zeit, um ohne Angst zu sprechen. Jedes kleine Gespräch ist schon ein Schritt.',\n         'Die Sprache ist im Werden: Du nutzt sie schon, aber vielleicht noch angespannt oder nur in vertrauten Situationen. Jetzt zählt Regelmässigkeit, nicht Perfektion.',\n         'Die Sprache ist deine Stütze. Du sprichst, lernst und hast keine Angst vor Fehlern. Das öffnet die Tür zu allem anderen: zur Arbeit, zu Menschen und zum Gefühl, dass du hier kein Gast bist.'],\n    recs: ['Wähle pro Woche eine Situation, in der du nur die Landessprache sprichst: im Café, im Laden, mit den Nachbarn.',\n           '15 Minuten Sprache jeden Tag sind besser als zwei Stunden einmal pro Woche. Eine Serie, ein Podcast oder eine App passen gut.',\n           'Such dir einen Tandempartner oder einen Konversationsclub: Dort lernen alle und machen gemeinsam Fehler.'],\n    focus: 'mutiger in der neuen Sprache zu sprechen' },\n  { name: 'Alltag und System', short: 'Alltag',\n    items: ['Ich erledige Dokumente, Briefe, Versicherung und Rechnungen in Ruhe.',\n            'Ich weiss, an wen ich mich wenden kann, wenn etwas passiert: Ärztin oder Arzt, Behörde, Versicherung, Anwalt.',\n            'Ich nutze die Dienste vor Ort: Verkehrsmittel, Bank, Post, Apps.',\n            'Ich verstehe die Regeln und ungeschriebenen Normen hier und halte mich daran ohne inneren Widerstand.',\n            'Ich mache mein Zuhause gemütlich: mit Dingen, Ordnung und Kleinigkeiten, die mir gefallen.'],\n    lv: ['Alltag und System fallen dir noch schwer. Briefe, Dokumente und Regeln des neuen Landes können Angst machen und viel Kraft kosten. Das erleben fast alle, die umziehen.',\n         'Im Alltag findest du dich schon zurecht, aber manche Dinge machen dir noch Sorgen oder kosten viel Kraft. Noch etwas Erfahrung, und das System wird verständlicher.',\n         'Alltag und System sind deine Stütze. Du weisst, wie alles funktioniert, und handelst sicher. Das macht Kraft frei für das, was wirklich wichtig ist.'],\n    recs: ['Leg einen Ordner für alle Dokumente und Briefe an und geh ihn einmal pro Woche durch, immer zur gleichen Zeit.',\n           'Schreib eine Liste «Wen rufe ich an, wenn…»: Ärztin oder Arzt, Versicherung, Behörde, Notdienste.',\n           'Frag Einheimische oder erfahrene Emigrantinnen und Emigranten nach den ungeschriebenen Regeln. Vieles ist einfacher, als es scheint.'],\n    focus: 'dich im neuen System sicherer zu fühlen' },\n  { name: 'Arbeit und Entfaltung', short: 'Arbeit',\n    items: ['Ich mache Schritte hin zu einer Arbeit oder Tätigkeit, die zu mir passt: Ausbildung, Lebenslauf, Projekte, Vorstellungsgespräche.',\n            'Ich nutze meine Fähigkeiten und Erfahrung und mache nicht nur das, was sich gerade ergibt.',\n            'Ich finde heraus, wie der Arbeitsmarkt und mein Beruf im neuen Land funktionieren.',\n            'Ich bringe zu Ende, was ich angefangen habe, und sehe das Ergebnis meiner Mühe.',\n            'Ich spreche über meine Fähigkeiten und Erfolge laut, ohne sie kleinzureden.'],\n    lv: ['Arbeit und Entfaltung klingen gerade leise. Nach dem Umzug verlieren viele vorübergehend ihren beruflichen Halt, und das ist eines der empfindlichsten Themen. Wichtig ist: Deine Erfahrung ist nicht verschwunden.',\n         'Du bewegst dich in Richtung deiner Tätigkeit, aber vielleicht noch nicht dorthin, wo du hinwillst, oder du nutzt nicht alles, was du kannst. Das ist eine Zwischenphase, und es gibt einen Weg hinaus.',\n         'Arbeit und Entfaltung sind deine Stütze. Du nutzt deine Stärken und siehst Ergebnisse. Das gibt dir Sicherheit und das Gefühl, am richtigen Platz zu sein.'],\n    recs: ['Schreib 10 deiner Fähigkeiten und Erfolge auf, auch aus deinem früheren Leben. Lies sie vor wichtigen Gesprächen wieder durch.',\n           'Sprich mit zwei Menschen, die in diesem Land schon in deinem Bereich arbeiten. Frag sie, wie sie angefangen haben.',\n           'Setz dir ein kleines Ziel für den Monat: ein Kurs, ein Lebenslauf, ein Projekt oder ein Treffen.'],\n    focus: 'eine Tätigkeit zu finden, in der du dich entfalten kannst' },\n  { name: 'Menschen und Beziehungen', short: 'Menschen',\n    items: ['Ich treffe Freunde oder Bekannte im neuen Land persönlich.',\n            'Ich habe Kontakt mit Einheimischen und nicht nur mit Russischsprachigen.',\n            'Ich halte den Kontakt zu meinen Lieben in der Heimat so, dass er mich wärmt und nicht belastet.',\n            'Ich mache bei etwas gemeinsam mit anderen mit: Kurse, Vereine, Freiwilligenarbeit, Sport, Eltern-Chats.',\n            'Ich teile meine Sorgen mit mindestens einem Menschen und bekomme Unterstützung.'],\n    lv: ['Die Beziehungen zu Menschen klingen gerade leise. Einsamkeit ist eine häufige Begleiterin der Emigration, auch wenn die Familie da ist. Neue Beziehungen wachsen langsam, und das sagt nichts Schlechtes über dich.',\n         'Du hast Menschen um dich, aber vielleicht fehlt es an Tiefe oder Vielfalt: nur die eigenen Leute oder nur Kontakte über die Arbeit. Hier ist der nächste Schritt leicht.',\n         'Menschen und Beziehungen sind deine Stütze. Du hast jemanden, mit dem du Freude und Schwierigkeiten teilen kannst, im alten wie im neuen Leben. Das ist einer der stärksten Schutzfaktoren gegen Stress.'],\n    recs: ['Wähle eine regelmässige Aktivität mit anderen Menschen: Sport, Chor, Kurs, Freiwilligenarbeit. Aus Regelmässigkeit entsteht Freundschaft.',\n           'Lade selbst jemanden auf einen Kaffee ein. Viele warten auch darauf, eingeladen zu werden.',\n           'Vereinbare feste Zeiten für Anrufe mit deinen Lieben in der Heimat, damit der Kontakt warm bleibt und nicht beunruhigt.'],\n    focus: 'deine Menschen im neuen Land zu finden' },\n  { name: 'Kraft: Körper und Erholung', short: 'Kraft',\n    items: ['Ich schlafe genug und wache erholt auf.',\n            'Ich bewege mich: Spaziergänge, Sport, Natur.',\n            'Ich mache etwas nur zum Vergnügen, ohne Nutzen und Ziel.',\n            'Ich merke, wenn ich müde bin, und gönne mir eine Pause, statt mich «durchzubeissen».',\n            'Ich fahre an schöne Orte im neuen Land und geniesse sie.'],\n    lv: ['Du hast gerade wenig Kraft. Die Anpassung kostet sehr viel Energie, und oft meldet der Körper die Müdigkeit als Erstes. Das ist keine Schwäche, sondern ein Zeichen, dass du Fürsorge brauchst.',\n         'Du sorgst für dich, aber nicht immer. Wenn es schwer wird, fallen Erholung und Vergnügen als Erstes weg. Es lohnt sich, sie fest in den Alltag einzuplanen.',\n         'Körper und Erholung sind deine Stütze. Du kannst dich erholen, dich bewegen und dich freuen. Das ist der Treibstoff für alle anderen Bereiche.'],\n    recs: ['Gönn dir jeden Tag ein kleines Vergnügen ohne Nutzen: Kaffee auf dem Balkon, Musik, einen Spaziergang.',\n           'Beweg dich mindestens 20 Minuten am Tag. Ein Spaziergang zählt auch.',\n           'Entdecke einmal pro Woche einen neuen schönen Ort im Land. So wird das neue Land nach und nach zu deinem.'],\n    focus: 'wieder Kraft und Freude zu gewinnen' },\n  { name: 'Ich und Sinn', short: 'Sinn',\n    items: ['Ich mache, was mir persönlich wichtig ist, und nicht nur, was ich «muss».',\n            'Ich habe ein Bild davon, wie mein Leben hier in einem Jahr aussehen soll, und mache Schritte dorthin.',\n            'Ich merke, was in mir durch den Umzug gewachsen ist und sich verändert hat.',\n            'Ich treffe Entscheidungen nach meinen eigenen Werten und nicht nach den Erwartungen anderer.',\n            'Ich erlaube mir, ich selbst zu sein: Ich spreche, kleide mich und erhole mich so, wie es mir entspricht.'],\n    lv: ['Das Gefühl für dich selbst und für den Sinn klingt gerade leise. Nach dem Umzug haben viele das Gefühl, einen Teil von sich verloren zu haben: frühere Rollen, Status, vertrauten Halt. Das ist eine Zeit, in der du dich neu zusammensetzen kannst.',\n         'Du suchst dich im neuen Leben und findest schon Halt. Manchmal kommt das Gefühl zurück, nicht dein eigenes Leben zu leben. Das gehört zum Weg.',\n         'Du bleibst du selbst und lebst nach deinen Werten. Der Umzug war nicht nur eine Prüfung, sondern auch Wachstum. Das ist die tiefste Stütze der Anpassung.'],\n    recs: ['Schreib jeden Abend eine Sache auf, die heute genau dir wichtig war.',\n           'Beschreibe, wie dein Leben hier in einem Jahr aussehen soll. Wähle einen Schritt dorthin.',\n           'Erinnere dich, was dir vor dem Umzug Kraft gegeben hat. Was davon kannst du hier zurückholen?'],\n    focus: 'dich selbst und deinen Platz in der neuen Welt zu finden' }\n];\nconst CULT = [\n  { name: 'Verbindung zur eigenen Kultur',\n    items: ['Ich spreche meine Muttersprache zu Hause oder mit Freunden.',\n            'Ich koche vertrautes Essen, feiere die Feste und pflege die Traditionen meiner Kultur.',\n            'Ich lese, schaue oder höre etwas in meiner Muttersprache.',\n            'Ich habe im neuen Land Kontakt mit Menschen aus meiner Kultur.',\n            'Ich gebe meinen Kindern oder Nahestehenden etwas Wichtiges aus meiner Kultur weiter.'] },\n  { name: 'Verbindung zur neuen Kultur',\n    items: ['Ich probiere einheimisches Essen, Feste und Bräuche aus.',\n            'Ich schaue lokale Nachrichten und Filme und höre lokale Musik.',\n            'Ich gehe zu Veranstaltungen vor Ort: Märkte, Feste, Versammlungen.',\n            'Ich habe ausserhalb der Arbeit Kontakt mit Einheimischen.',\n            'Ich lerne die Geschichte und die Besonderheiten des Landes kennen, in dem ich lebe.'] }\n];\nconst YEARS = ['weniger als 6 Monate','6–12 Monate','1–3 Jahre','3–5 Jahre','mehr als 5 Jahre'];\nconst STAGES = [\n  { phrase: 'Alles ist neu und spannend, ich entdecke viel.', name: 'Zeit der Entdeckungen',\n    text: 'Alles ist neu und inspiriert dich. Das ist eine wunderbare Zeit, um Stützen zu legen: Sprache, Bekanntschaften, Gewohnheiten. Mit der Zeit kann die Begeisterung in Müdigkeit übergehen, und das ist ein normaler Teil des Weges.' },\n  { phrase: 'Es ist schwieriger geworden: viel Müdigkeit, Gereiztheit, ich habe Heimweh.', name: 'Zeit der Schwierigkeiten',\n    text: 'Gerade kann es schwer sein: Müdigkeit, Gereiztheit, Heimweh. Das ist die häufigste und natürlichste Phase der Anpassung. Sie geht vorbei, besonders wenn Unterstützung da ist.' },\n  { phrase: 'Ich gewöhne mich nach und nach ein und finde meine Wege und meinen Halt.', name: 'Zeit des Halts',\n    text: 'Du findest nach und nach deine eigenen Wege, hier zu leben. Schwierigkeiten gibt es noch, aber du hast immer mehr Halt. Jetzt ist eine gute Zeit, das zu stärken, was schon funktioniert.' },\n  { phrase: 'Hier ist mein Zuhause, ich kann ich selbst sein.', name: 'Wie zu Hause',\n    text: 'Hier ist dein Zuhause, und du kannst du selbst sein. Das ist das Ergebnis eines langen Weges. Jetzt kannst du nicht nur darüber nachdenken, wie du zurechtkommst, sondern auch darüber, was du dir wünschst.' },\n  { phrase: 'Nach einer ruhigen Zeit ist es wieder schwieriger geworden.', name: 'Neue Runde',\n    text: 'Nach einer stabilen Zeit ist es wieder schwieriger geworden. Das kommt vor: Die Anpassung verläuft nicht geradlinig, sondern in Wellen. Eine neue Welle ist kein Rückschritt, sondern eine Einladung zum nächsten Schritt.' }\n];\nconst STRATEGY = {\n  both: ['Brücke zwischen den Welten', 'Du bewahrst deine Kultur behutsam und öffnest dich gleichzeitig der neuen. In der Psychologie der Anpassung nennt man das Integration, und es ist der stabilste Weg: Du hast Wurzeln und Flügel. Wichtig ist, weiter beide Ufer zu halten und dich von der doppelten Belastung nicht erschöpfen zu lassen.'],\n  newOnly: ['Neues Leben ganz von vorn', 'Du gehst aktiv in die neue Kultur hinein, und die Verbindung zu deiner eigenen ist leiser geworden. Das hilft dir, dich schnell einzuleben. Manchmal geht mit der Vergangenheit aber auch ein Teil des Halts verloren. Überleg dir, was du aus deiner Kultur für dich und deine Lieben bewahren möchtest.'],\n  ownOnly: ['Eigene Insel', 'Du bewahrst deine Kultur, deine Sprache und deine Gewohnheiten, und das neue Land bleibt noch etwas am Rand. Das gibt dir Sicherheit und Wärme. Der nächste Schritt: nach und nach Brücken zur neuen Kultur bauen, ohne das Eigene zu verlieren.'],\n  none: ['Zwischen zwei Ufern', 'Gerade klingt die Verbindung sowohl zur eigenen als auch zur neuen Kultur leise. Das ist oft so in Zeiten der Müdigkeit oder direkt nach dem Umzug, wenn die Kraft nur für das Wichtigste reicht. Das bleibt nicht für immer so. Schon kleine Schritte zu Menschen und Traditionen, den eigenen und den neuen, helfen dir, Halt zu spüren.']\n};\nconst LV_NAME = ['klingt noch leise','im Werden','deine Stütze'];\nconst KEEP = 'Dieser Bereich arbeitet schon für dich. Behalte bei, was du tust, und stütz dich auf ihn, wenn es schwer wird.';\nconst LABELS = ['nie','1–2 Mal','manchmal','oft','fast immer'];\nconst AC = ['--a0','--a1','--a2','--a3','--a4','--a5'];\nconst AS = ['--a0s','--a1s','--a2s','--a3s','--a4s','--a5s'];\n\n/* ---------- состояние ---------- */\n// шаги: 0 — о переезде; 1–3 — по две сферы; 4 — две культуры\nlet step = 0, ctx = { years: null, stage: null }, ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\nlet myName = '', last = null;\nconst $ = id => document.getElementById(id);\nconst css = v => getComputedStyle(document.documentElement).getPropertyValue(v).trim();\nconst sum = a => a.reduce((x, y) => x + y, 0);\nconst esc = s => String(s).replace(/[&<>\"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst lvl = s => s <= 7 ? 0 : s <= 13 ? 1 : 2;\nconst TOTAL = 5 * 6 + 10 + 2;\n\n$('startBtn').addEventListener('click', () => {\n  myName = $('nameMe').value.trim();\n  resetInvite(); window.__leadCountry = '';\n  step = 0; ctx = { years: null, stage: null };\n  ans = { areas: AREAS.map(() => Array(5).fill(null)), cult: CULT.map(() => Array(5).fill(null)) };\n  $('intro').hidden = true; $('quiz').hidden = false; renderStep(); window.scrollTo(0, 0);\n});\n\nfunction choiceGroup(title, opts, key){\n  const wrap = document.createElement('div'); wrap.className = 'q';\n  wrap.innerHTML = `<p>${title}</p><div class=\"choices1\" role=\"group\"></div>`;\n  const g = wrap.querySelector('.choices1');\n  opts.forEach((o, i) => {\n    const b = document.createElement('button'); b.className = 'opt1'; b.id = `c-${key}-${i}`; b.textContent = o;\n    b.setAttribute('aria-pressed', ctx[key] === i ? 'true' : 'false');\n    b.addEventListener('click', () => { ctx[key] = i; g.querySelectorAll('.opt1').forEach((x, n) => x.setAttribute('aria-pressed', n === i ? 'true' : 'false')); update(); });\n    g.appendChild(b);\n  });\n  return wrap;\n}\nfunction scaleItem(text, num, arr, i, idPrefix){\n  const q = document.createElement('div'); q.className = 'q';\n  q.innerHTML = `<p><span class=\"n\">${num}.</span>${text}</p><div class=\"opts\" role=\"group\" aria-label=\"Bewertung\"></div>`;\n  const opts = q.querySelector('.opts');\n  for (let v = 0; v <= 4; v++){\n    const o = document.createElement('button'); o.className = 'opt'; o.id = `${idPrefix}-${i}-${v}`;\n    o.setAttribute('aria-pressed', arr[i] === v ? 'true' : 'false');\n    o.innerHTML = `<b>${v}</b><small>${LABELS[v]}</small>`;\n    o.addEventListener('click', () => { arr[i] = v; opts.querySelectorAll('.opt').forEach((x, n) => x.setAttribute('aria-pressed', n === v ? 'true' : 'false')); update(); });\n    opts.appendChild(o);\n  }\n  return q;\n}\nfunction renderStep(){\n  const list = $('qlist'); list.innerHTML = '';\n  $('stepLabel').textContent = `Schritt ${step + 1} von 5`;\n  if (step === 0){\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Über deinen Umzug';\n    $('roleTitle').textContent = 'Wo du gerade stehst'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Zwei kurze Fragen, damit die Auswertung genauer wird.';\n    list.appendChild(choiceGroup('Wie lange lebst du schon im neuen Land?', YEARS, 'years'));\n    list.appendChild(choiceGroup('Welcher Satz passt gerade am besten zu dir?', STAGES.map(s => s.phrase), 'stage'));\n  } else if (step <= 3){\n    const pair = [(step - 1) * 2, (step - 1) * 2 + 1];\n    document.documentElement.style.setProperty('--accent', `var(${AC[pair[0]]})`);\n    $('partTag').textContent = 'Bereiche des neuen Lebens · in den letzten 4 Wochen';\n    $('roleTitle').textContent = `${AREAS[pair[0]].name} · ${AREAS[pair[1]].name}`; $('roleTitle').style.color = `var(${AC[pair[0]]})`;\n    $('roleSub').textContent = 'Kreuze an, wie oft das wirklich so war.';\n    let n = (step - 1) * 10;\n    pair.forEach(a => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.style.color = `var(${AC[a]})`; h.textContent = AREAS[a].name; list.appendChild(h);\n      AREAS[a].items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.areas[a], i, `a${a}`)));\n    });\n  } else {\n    document.documentElement.style.setProperty('--accent', 'var(--plum)');\n    $('partTag').textContent = 'Zwei Kulturen · in den letzten 4 Wochen';\n    $('roleTitle').textContent = 'Deine Kultur und die neue'; $('roleTitle').style.color = 'var(--plum)';\n    $('roleSub').textContent = 'Hier gibt es keine richtige Balance. Wichtig ist nur zu sehen, wie es bei dir gerade ist.';\n    let n = 30;\n    CULT.forEach((c, k) => {\n      const h = document.createElement('div'); h.className = 'qhead'; h.textContent = c.name; list.appendChild(h);\n      c.items.forEach((t, i) => list.appendChild(scaleItem(t, ++n, ans.cult[k], i, `c${k}`)));\n    });\n  }\n  $('next').textContent = step === 4 ? 'Auswertung anzeigen' : 'Weiter';\n  update();\n}\nfunction doneCount(){\n  return (ctx.years !== null) + (ctx.stage !== null) + ans.areas.flat().filter(v => v !== null).length + ans.cult.flat().filter(v => v !== null).length;\n}\nfunction stepComplete(){\n  if (step === 0) return ctx.years !== null && ctx.stage !== null;\n  if (step <= 3) return [(step - 1) * 2, (step - 1) * 2 + 1].every(a => ans.areas[a].every(v => v !== null));\n  return ans.cult.every(c => c.every(v => v !== null));\n}\nfunction update(){\n  const d = doneCount();\n  $('countLabel').textContent = `${d} von ${TOTAL}`;\n  $('prog').style.width = (d / TOTAL * 100) + '%';\n  $('next').disabled = !stepComplete();\n}\n$('next').addEventListener('click', () => { if (step < 4){ step++; renderStep(); window.scrollTo(0, 0); } else showResult(); });\n$('back').addEventListener('click', () => {\n  if (step > 0){ step--; renderStep(); window.scrollTo(0, 0); }\n  else { $('quiz').hidden = true; $('intro').hidden = false; }\n});\n\n/* ---------- картинки ---------- */\nfunction aIcon(k){\n  const c = css(AC[k]);\n  const p = [\n    `<path d=\"M4 5h16v10H9l-5 4z\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\" stroke-linejoin=\"round\"/>`,\n    `<path d=\"M3 11.2 12 3.5l9 7.7V21h-6.2v-5.6H9.2V21H3z\" fill=\"${c}\"/>`,\n    `<path d=\"M12 3l2.6 5.6 6 .7-4.5 4.1 1.2 6L12 16.4 6.7 19.4l1.2-6L3.4 9.3l6-.7z\" fill=\"${c}\"/>`,\n    `<circle cx=\"8\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><circle cx=\"16\" cy=\"9\" r=\"3.4\" fill=\"${c}\"/><path d=\"M2.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5M10.5 20c.6-3.6 3-5.5 5.5-5.5s4.9 1.9 5.5 5.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2\"/>`,\n    `<path d=\"M12 21s-7.5-4.6-7.5-10.2A4.3 4.3 0 0 1 12 8a4.3 4.3 0 0 1 7.5 2.8C19.5 16.4 12 21 12 21z\" fill=\"${c}\"/>`,\n    `<circle cx=\"12\" cy=\"12\" r=\"8.5\" fill=\"none\" stroke=\"${c}\" stroke-width=\"2.2\"/><circle cx=\"12\" cy=\"12\" r=\"3\" fill=\"${c}\"/>`][k];\n  return `<svg viewBox=\"0 0 24 24\" width=\"24\" height=\"24\" aria-hidden=\"true\">${p}</svg>`;\n}\nconst bar = (v, max, color) => `<div class=\"bar\"><i style=\"width:${v / max * 100}%;background:${color}\"></i></div>`;\n\n/* ---------- разбор ---------- */\nfunction compute(){\n  const sc = ans.areas.map(sum);\n  const own = sum(ans.cult[0]), neu = sum(ans.cult[1]);\n  const key = own >= 10 && neu >= 10 ? 'both' : neu >= 10 ? 'newOnly' : own >= 10 ? 'ownOnly' : 'none';\n  const idx = Math.round(sum(sc) / 120 * 100);\n  const strong = sc.indexOf(Math.max(...sc)), weak = sc.lastIndexOf(Math.min(...sc));\n  return { sc, own, neu, key, idx, strong, weak };\n}\nfunction buildBlocks(){\n  const r = compute(); last = r;\n  const N = esc(myName);\n  const [sName, sText] = STRATEGY[r.key];\n  const st = STAGES[ctx.stage];\n  const date = new Date().toLocaleDateString(DATE_LOCALE, { day: 'numeric', month: 'long', year: 'numeric' });\n  const B = [];\n\n  B.push({ html: `<div class=\"blk hero k-hero\"><div class=\"split\">\n      <div class=\"stack\" style=\"gap:10px\"><div class=\"eyebrow\">Kompass der Anpassung · Auswertung</div>\n        ${N ? `<div class=\"names\">${N}</div>` : ''}\n        <h1>${sName}</h1>\n        <p class=\"note\">${date} · im Land: ${YEARS[ctx.years]} · Phase: ${st.name}</p></div>\n      <div class=\"fig\" style=\"flex:0 0 150px;width:150px\">${compassSVG()}</div></div></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Zwei Kulturen</div><h2>Dein Weg zwischen zwei Kulturen</h2>\n      <div style=\"max-width:460px;width:100%;margin:0 auto\">${shoresSVG(r.own, r.neu)}</div>\n      <h3>${sName}</h3><p>${sText}</p>\n      <p class=\"note\">Eigene Kultur: <b>${r.own} von 20</b> · neue Kultur: <b>${r.neu} von 20</b>. Ab 10 Punkten gilt die Verbindung als stark.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Phase der Anpassung</div><h2>${st.name}</h2>${journeySVG(ctx.stage)}<p>${st.text}</p>\n      <p class=\"note\">Die Phasen sind nach dem klassischen Modell der Anpassung an eine neue Kultur beschrieben (U-Kurve). Jeder Mensch hat sein eigenes Tempo, und Phasen können sich wiederholen.</p></div>` });\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Sechs Bereiche</div><h2>Sechs Bereiche deines neuen Lebens</h2>${flowerSVG(r.sc)}\n      <p class=\"note\">Jeder Bereich hat 0 bis 20 Punkte. Gesamtindex der Anpassung: <b>${r.idx}%</b>. Das ist keine Bewertung, sondern ein Ausgangspunkt.</p></div>` });\n  B.push({ html: testInfoHtml() });\n\n  B.push({ newPage: true, html: `<div class=\"blk plain\"><div class=\"eyebrow\">Die Bereiche im Detail</div><h2>Wo dein Halt ist und wo es noch leise ist</h2>\n      <p>Dein stärkster Bereich ist gerade <b style=\"color:var(${AC[r.strong]})\">${AREAS[r.strong].name}</b>. Auf ihn kannst du dich stützen. Am leisesten ist <b style=\"color:var(${AC[r.weak]})\">${AREAS[r.weak].name}</b>. Hier lässt sich gut beginnen.</p></div>` });\n  r.sc.forEach((s, k) => {\n    const l = lvl(s);\n    const recs = l === 2 ? `<p class=\"recs\" style=\"padding-left:14px\">${KEEP}</p>`\n      : `<div class=\"recs-t\">Was dir hilft</div><ul class=\"recs\">${AREAS[k].recs.map(x => `<li>${x}</li>`).join('')}</ul>`;\n    B.push({ html: `<div class=\"blk role-blk\" style=\"--c:var(${AC[k]});--cs:var(${AS[k]})\">\n      <div class=\"role-head\"><div class=\"ico\">${aIcon(k)}</div><h3>${AREAS[k].name}</h3>\n        <span class=\"pill\" style=\"background:var(${AC[k]})\">${LV_NAME[l]}</span><span class=\"sc\">${s} / 20</span></div>\n      <p>${AREAS[k].lv[l]}</p>${recs}</div>` });\n  });\n\n  const low = AREAS[r.weak].items.map((t, i) => [t, ans.areas[r.weak][i]]).sort((a, b) => a[1] - b[1]).slice(0, 2);\n  const ritual = ['Mach einmal pro Woche etwas zum ersten Mal im neuen Land: ein Ort, ein Gericht, ein Anlass.',\n                  'Erhol dich einmal pro Woche richtig: ohne Aufgaben, ohne Handy, mit dem, was dich auftankt.',\n                  'Halte einmal pro Woche fest, was schon gelungen ist. Kleine Erfolge zählen auch.',\n                  'Denk einmal im Monat darüber nach, was du dir hier als Nächstes wünschst, und wähle einen Schritt.',\n                  'Tu dir einmal pro Woche etwas Gutes und sprich mit jemandem, der dich unterstützt.'][ctx.stage];\n  B.push({ html: `<div class=\"blk\"><div class=\"eyebrow\">Plan für 4 Wochen</div><h2>Kleine Schritte, die das Leben verändern</h2>\n    <div class=\"steps\">\n      <div><span class=\"num\">1</span><div><b>Dein Wachstumsbereich: ${AREAS[r.weak].name}</b><p>Wähle eine Handlung und setze sie mindestens zweimal pro Woche um:</p>\n        <ul class=\"clean\" style=\"margin-top:6px\">${low.map(([t]) => `<li>${t}</li>`).join('')}</ul></div></div>\n      <div><span class=\"num\">2</span><div><b>Deine Stütze: ${AREAS[r.strong].name}</b><p>Wenn es schwer wird, stütz dich auf diesen Bereich. Achte darauf, was dir hier gelingt, und lass ihn die anderen Bereiche tragen.</p></div></div>\n      <div><span class=\"num\">3</span><div><b>Ritual für die Phase «${st.name}»</b><p>${ritual}</p></div></div>\n      <div><span class=\"num\">4</span><div><b>In 4 Wochen</b><p>Mach den Test noch einmal und schau, wie sich dein Kompass verändert hat.</p></div></div>\n    </div></div>` });\n  B.push({ html: `<div class=\"blk\"><h2>Fragen zum Nachdenken</h2><p class=\"note\">Lass dir Zeit mit den Antworten. Du kannst sie aufschreiben oder einfach eine Weile bei ihnen bleiben.</p>\n    <ul class=\"clean\">\n      <li>Wenn du an deinem Platz bist, bist du wie was? Womit ist das vergleichbar?</li>\n      <li>Was hilft dir im neuen Land schon? Was könnte dir noch helfen?</li>\n      <li>Was wünschst du dir für dich in diesem Land?</li>\n      <li>Was aus deinem früheren Leben möchtest du bewahren, und was darfst du behutsam loslassen?</li>\n      <li>Wer oder was unterstützt dich hier?</li>\n      <li>Welcher kleine Schritt bringt dich diese Woche näher an das Gefühl «ich bin zu Hause»?</li>\n    </ul></div>` });\n\n  B.push({ html: inviteHtml({ name: myName, country: window.__leadCountry || '', interest: surveyAnswers().interest,\n                              focus: { coach: AREAS[r.weak].focus, psy: 'in eurer Beziehung mehr Wärme und Verständnis entsteht' } }) });\n  B.push({ html: moreTestsHtml(TEST_META.id) });\n  B.push({ html: authorHtml() });\n  B.push({ html: disclaimerHtml() });\n  r.sName = sName;\n  return B;\n}\nfunction showResult(){\n  $('report').innerHTML = buildBlocks().map(b => b.html).join('');\n  $('quiz').hidden = true; $('result').hidden = false; window.scrollTo(0, 0);\n}\n\n/* ---------- связь с общей анкетой ---------- */\nconst LEAD_HOOKS = {\n  personName: () => myName,\n  fileBase: () => 'Kompas_adaptatsii',\n  fileNames: () => myName ? [myName] : [],\n  payload: () => {\n    const r = last, scores = {};\n    AREAS.forEach((a, k) => scores[a.name] = r.sc[k]);\n    scores['Своя культура'] = r.own; scores['Новая культура'] = r.neu; scores['Индекс адаптации, %'] = r.idx;\n    return { result: r.sName, scores, notes: `в стране: ${YEARS[ctx.years]}; этап: ${STAGES[ctx.stage].name}; опора: ${AREAS[r.strong].name}; рост: ${AREAS[r.weak].name}` };\n  }\n};\n\n/* значки на плитках сфер на стартовой странице */\ndocument.querySelectorAll('.k-roles .role').forEach((el, k) => {\n  const b = el.querySelector('b'); if (!b) return;\n  const w = document.createElement('div'); w.className = 'ri';\n  w.innerHTML = aIcon(k); b.parentNode.insertBefore(w, b); w.appendChild(b);\n});\n", "/* =====================================================================\n   Общая анкета перед PDF, отправка в Google Таблицу и сборка PDF.\n   Тест задаёт: TEST_META {id, name}, buildBlocks(), showResult(), LEAD_HOOKS.\n   ===================================================================== */\n/* Страны — коды ISO; названия показываются на языке страницы, в таблицу уходит русское название. */\nconst COUNTRY_TOP = ['CH','DE','AT','FR','IT','ES','NL','BE','GB','PL','CZ','IL','US','CA','UA','RU','BY','KZ'];\nconst COUNTRY_ALL = ['AU','AT','AZ','AL','DZ','AD','AR','AM','AF','BD','BH','BY','BE','BG','BO','BA','BR','GB','HU','VE','VN','GH','DE','HK','GR','GE','DK','DO','EG','IL','IN','ID','JO','IQ','IR','IE','IS','ES','IT','KZ','KH','CA','QA','KE','CY','KG','CN','CO','CR','CU','KW','LV','LB','LT','LI','LU','MU','MY','MV','MT','MA','MX','MD','MC','MN','ME','NP','NG','NL','NZ','NO','AE','OM','PK','PA','PY','PE','PL','PT','RU','RO','SA','MK','RS','SG','SK','SI','US','TJ','TH','TW','TN','TM','TR','UG','UZ','UA','UY','PH','FI','FR','HR','CZ','CL','CH','SE','LK','EC','EE','ZA','KR','JM','JP'];\nconst PAGE_LANG = (typeof LANG !== 'undefined') ? LANG : 'ru';\nconst countryName = (() => { try { const d = new Intl.DisplayNames([PAGE_LANG], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst countryRu = (() => { try { const d = new Intl.DisplayNames(['ru'], { type:'region' }); return c => d.of(c); } catch(e){ return c => c; } })();\nconst COUNTRIES = COUNTRY_ALL.map(countryRu);\nconst OTHER_COUNTRY = 'Другая страна';\n\nfunction leadFormHtml(){\n  return `<div class=\"blk actions\" style=\"margin-top:18px\">\n    <h3>Auswertung als PDF erhalten</h3>\n    <p>Ein schönes PDF mit deiner Auswertung, ohne die Testfragen: Bilder, Beschreibungen, Empfehlungen, ein Plan für 4 Wochen und Fragen zum Nachdenken. Hinterlasse deine Kontaktdaten, und die Datei wird sofort heruntergeladen.</p>\n    <form id=\"lead\" class=\"stack\" style=\"gap:12px\" novalidate>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fName\">Name *</label><input id=\"fName\" maxlength=\"40\" required autocomplete=\"given-name\"></div>\n        <div class=\"field\"><label for=\"fEmail\">E-mail *</label><input id=\"fEmail\" type=\"email\" maxlength=\"80\" required autocomplete=\"email\"></div>\n      </div>\n      <div class=\"field\"><label for=\"fContact\">Telegram oder WhatsApp</label><input id=\"fContact\" maxlength=\"60\" placeholder=\"@username oder +41 …\"></div>\n      <div class=\"row\" style=\"align-items:stretch\">\n        <div class=\"field\"><label for=\"fCountry\">Land *</label><select id=\"fCountry\" required><option value=\"\">Wähle ein Land</option></select></div>\n        <div class=\"field\"><label for=\"fCity\">Stadt</label><input id=\"fCity\" maxlength=\"40\" autocomplete=\"address-level2\"></div>\n      </div>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fConsent\" required> <span>Ich bin einverstanden, dass meine Daten verarbeitet werden, um mir die Ergebnisse zu senden und mit mir Kontakt aufzunehmen *</span></label>\n      <label class=\"check\"><input type=\"checkbox\" id=\"fNews\"> <span>Ich möchte hilfreiche Materialien über Beziehungen, Anpassung und das Leben in der Emigration erhalten</span></label>\n      <p class=\"err\" id=\"formErr\" hidden></p>\n      <div class=\"row\">\n        <button class=\"btn\" type=\"submit\" id=\"pdfBtn\">PDF erhalten</button>\n        <button class=\"btn ghost\" type=\"button\" id=\"again\">Noch einmal machen</button>\n      </div>\n      <p class=\"note\">Deine Daten sieht nur Iryna Voznesenskaya. Sie werden nicht an Dritte weitergegeben.</p>\n    </form>\n    <span class=\"status\" id=\"status\" hidden></span>\n  </div>`;\n}\ndocument.querySelectorAll('[data-lead]').forEach(el => el.innerHTML = leadFormHtml());\n(function fillCountries(){\n  const sel = document.getElementById('fCountry'); if (!sel) return;\n  const g1 = document.createElement('optgroup'); g1.label = 'Häufig gewählt';\n  COUNTRY_TOP.forEach(c => g1.appendChild(new Option(countryName(c), countryRu(c))));\n  const g2 = document.createElement('optgroup'); g2.label = 'Alle Länder';\n  COUNTRY_ALL.map(c => [countryName(c), countryRu(c)]).sort((x, y) => x[0].localeCompare(y[0], PAGE_LANG)).forEach(([n, v]) => g2.appendChild(new Option(n, v)));\n  g2.appendChild(new Option('Anderes Land', OTHER_COUNTRY));\n  sel.appendChild(g1); sel.appendChild(g2);\n})();\n\nconst el = id => document.getElementById(id);\nfunction setStatus(t){ el('status').textContent = t; el('status').hidden = !t; }\nfunction setErr(t){ el('formErr').textContent = t; el('formErr').hidden = !t; }\nel('again').addEventListener('click', () => { el('result').hidden = true; el('intro').hidden = false; window.scrollTo(0,0); });\n\nconst LS = 'irinaTestsLead';\nfunction loadLead(){ try { return JSON.parse(localStorage.getItem(LS) || 'null'); } catch(e){ return null; } }\nfunction saveLead(v){ try { localStorage.setItem(LS, JSON.stringify(v)); } catch(e){} }\n\nconst _showResult = showResult;\nshowResult = function(){\n  _showResult();\n  const saved = loadLead();\n  el('fName').value = saved?.name || LEAD_HOOKS.personName() || '';\n  if (saved){\n    el('fEmail').value = saved.email || ''; el('fContact').value = saved.contact || '';\n    el('fCountry').value = (COUNTRIES.includes(saved.country) || saved.country === OTHER_COUNTRY) ? saved.country : '';\n    el('fCity').value = saved.city || '';\n  }\n  setErr(''); setStatus('');\n};\n\n// Чёткость PDF: 3 = около 290 точек на дюйм (хорошо для печати). На слабых телефонах — 2.5.\nconst PDF_SCALE = (/iPhone|iPad|Android/i.test(navigator.userAgent) && (navigator.deviceMemory || 4) < 4) ? 2.5 : 3;\nasync function buildPdf(){\n  const stage = el('stage'); stage.innerHTML = '';\n  const blocks = buildBlocks();\n  const pages = [];\n  const newPage = () => {\n    const p = document.createElement('div'); p.className = 'pdf-page';\n    p.innerHTML = `<div class=\"strip\"></div><div class=\"pbody\"></div><div class=\"pfoot\"><span>${footerLine()}</span><span class=\"pn\"></span></div>`;\n    stage.appendChild(p); pages.push(p); return p.querySelector('.pbody');\n  };\n  let body = newPage();\n  for (const b of blocks){\n    if (!b.html) continue;\n    if (b.newPage && body.children.length) body = newPage();\n    const holder = document.createElement('div'); holder.innerHTML = b.html; const node = holder.firstElementChild;\n    body.appendChild(node);\n    if (body.scrollHeight > body.clientHeight + 1 && body.children.length > 1){ node.remove(); body = newPage(); body.appendChild(node); }\n  }\n  pages.forEach((p, i) => p.querySelector('.pn').textContent = `${i+1} / ${pages.length}`);\n  if (document.fonts && document.fonts.ready) await document.fonts.ready;\n  const { jsPDF } = window.jspdf;\n  const pdf = new jsPDF({ unit:'pt', format:'a4', compress:true });\n  const bg = getComputedStyle(document.documentElement).getPropertyValue('--pdf-bg').trim() || '#FFFFFF';\n  for (let i = 0; i < pages.length; i++){\n    const canvas = await html2canvas(pages[i], { scale:PDF_SCALE, backgroundColor:'#FFFFFF', useCORS:true, logging:false });\n    if (i) pdf.addPage();\n    pdf.addImage(canvas.toDataURL('image/jpeg', 0.95), 'JPEG', 0, 0, 595.28, 841.89, undefined, 'FAST');\n    const pr = pages[i].getBoundingClientRect(), k = 595.28 / pr.width;\n    pages[i].querySelectorAll('a[href]').forEach(a => {\n      if (!/^https?:/.test(a.href)) return;\n      const r = a.getBoundingClientRect();\n      pdf.link((r.left - pr.left) * k, (r.top - pr.top) * k, r.width * k, r.height * k, { url: a.href });\n    });\n  }\n  stage.innerHTML = '';\n  return pdf.output('blob');\n}\n\nfunction translit(t){\n  const m = {а:'a',б:'b',в:'v',г:'g',д:'d',е:'e',ё:'e',ж:'zh',з:'z',и:'i',й:'y',к:'k',л:'l',м:'m',н:'n',о:'o',п:'p',р:'r',с:'s',т:'t',у:'u',ф:'f',х:'kh',ц:'ts',ч:'ch',ш:'sh',щ:'sch',ъ:'',ы:'y',ь:'',э:'e',ю:'yu',я:'ya',і:'i',ї:'yi',є:'ye',ґ:'g'};\n  return String(t).toLowerCase().split('').map(c => m[c] ?? c).join('').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');\n}\nlet downloadsCap = null;\n(async () => { try { if (window.claude && window.claude.use) downloadsCap = await window.claude.use('downloads'); } catch(e){ downloadsCap = null; } })();\nasync function saveBlob(blob, filename){\n  if (downloadsCap){ await downloadsCap.save({ filename, data: blob }); return; }\n  const url = URL.createObjectURL(blob);\n  const a = document.createElement('a');\n  a.href = url; a.download = filename; a.rel = 'noopener'; document.body.appendChild(a); a.click(); setTimeout(() => a.remove(), 1000);\n  setTimeout(() => URL.revokeObjectURL(url), 60000);\n}\n\nasync function sendLead(lead){\n  if (!ENDPOINT) return;\n  const src = new URLSearchParams(location.search);\n  const sv = surveyAnswers();\n  const t = LEAD_HOOKS.payload();\n  const payload = {\n    ...lead,\n    testId: TEST_META.id, testName: TEST_META.name, lang: PAGE_LANG,\n    heard: sv.heard.join(', '), interest: sv.interest.join(', '),\n    result: t.result, scores: t.scores, notes: t.notes || '',\n    source: src.get('utm_source') || src.get('src') || document.referrer || 'прямой заход'\n  };\n  try {\n    await fetch(ENDPOINT, { method:'POST', mode:'no-cors', headers:{ 'Content-Type':'text/plain;charset=utf-8' }, body: JSON.stringify(payload) });\n  } catch(e){ /* PDF всё равно выдаётся */ }\n}\n\nel('lead').addEventListener('submit', async (ev) => {\n  ev.preventDefault(); setErr('');\n  const lead = {\n    name: el('fName').value.trim(), email: el('fEmail').value.trim(), contact: el('fContact').value.trim(),\n    country: el('fCountry').value.trim(), city: el('fCity').value.trim(), marketing: el('fNews').checked\n  };\n  if (!lead.name) return setErr('Schreib bitte deinen Namen.');\n  if (!/^[^\\s@]+@[^\\s@]+\\.[^\\s@]{2,}$/.test(lead.email)) return setErr('Prüf bitte deine E-Mail-Adresse: Sie scheint einen Fehler zu enthalten.');\n  if (!lead.country) return setErr('Wähle bitte ein Land aus der Liste.');\n  if (!el('fConsent').checked) return setErr('Um das PDF zu erhalten, brauche ich dein Einverständnis zur Datenverarbeitung.');\n  if (!window.jspdf || !window.html2canvas) return setErr('Das PDF-Modul konnte nicht geladen werden. Prüf deine Internetverbindung und lade die Seite neu.');\n  const btn = el('pdfBtn'); btn.disabled = true; setStatus('PDF wird vorbereitet…');\n  try {\n    saveLead(lead);\n    window.__leadCountry = lead.country;\n    await sendLead(lead);\n    const blob = await buildPdf();\n    await saveBlob(blob, [LEAD_HOOKS.fileBase(), ...LEAD_HOOKS.fileNames().map(translit)].filter(Boolean).join('_') + '.pdf');\n    setStatus('Fertig! Das PDF ist gespeichert. Wenn es sich nicht geöffnet hat, schau im Ordner «Downloads» nach.');\n  } catch(e){\n    setStatus('');\n    setErr(e && e.code === 'declined' ? 'Speichern abgebrochen.' : 'Das PDF konnte nicht erstellt werden. Versuch es bitte noch einmal.');\n  } finally { btn.disabled = false; }\n});\nwindow.__buildPdf = buildPdf;\n"]};
